#!/usr/bin/env python3
"""A pull request never adds a committed generated file (Leo, 2026-10-21: "don't commit generatable stuff").

Generated outputs that are committed conflict on every base move: the base autofix
recommits them after merges and GitHub ignores the merge drivers. The cutover
(gitignore them, generate them at build time) is moving them out of git one generator
at a time. This guard keeps new ones from coming in meanwhile.

What is generated, in one place:
  scripts/ci/generated-files.json      each generator, the outputs it writes, its inputs and
                                       its status: "committed" (outputs still in git, pending
                                       cutover) or "build" (made at build time, never in git).
                                       Also the naming conventions (*.generated.*, generated/
                                       directories) and the files committed by design
                                       (lockfiles).
  scripts/cmux-next/generated_outputs.py OUTPUTS
                                       the exports the base autofix regenerates (#21946);
                                       every one counts as "committed". Read from each
                                       revision, like the manifest.
  a generated header                   "GENERATED by", "@generated", or "generated/built
                                       by|from ..." next to "do not edit" in a file's first
                                       lines, for a generator nobody listed yet.
  scripts/ci/generated-files-baseline.txt
                                       the generated files git still tracks that no
                                       "committed" generator covers. It may only shrink.

  generated_files_guard.py check --repo DIR --base REV --head REV
      The pull request's change from REV to REV (a merge commit and its first parent), with
      DIR's working tree at --head. Rules are read from --base, so a pull request cannot
      loosen them for itself. Fails (exit 1) when the change
        - adds a generated file that no "committed" generator owns (a new generator's output,
          an output of a generator already moved to build time, or a conventionally named one);
        - adds a "committed" generator or a generated_outputs.py export pattern, moves one from
          "build" back to "committed", or widens a committed generator's outputs, or adds a
          by-design exception without a ruling link;
        - adds a baseline line for a file the base did not track;
        - edits an output of a generator that declares its inputs without changing any of
          them (a hand edit the next regeneration would undo);
        - leaves a tracked generated file at --head that neither a committed generator nor the
          baseline covers.
  generated_files_guard.py baseline --repo DIR
      Prints the baseline for DIR's tracked files (the last rule's set), to write the file.
"""
from __future__ import annotations

import argparse
import fnmatch
import importlib.util
import json
import os
import re
import subprocess
import sys
import tempfile
from collections.abc import Iterable
from dataclasses import dataclass, field
from functools import lru_cache
from pathlib import Path

MANIFEST = "scripts/ci/generated-files.json"
BASELINE = "scripts/ci/generated-files-baseline.txt"
OUTPUTS = "scripts/cmux-next/generated_outputs.py"
# What generated_outputs.py reads beside itself; load_exports writes it next to the module.
SETTINGS_EXPORTS = "scripts/cmux-next/settings-exports.txt"

HEADER_BYTES = 2048
HEADER_LINES = 6
HEADER_LINE_CHARS = 240
# "GENERATED by" in capitals, or an @generated marker, opening a line (after comment marks, or as a
# "_comment" value) is a header on its own; inside a string literal or prose it is not. Otherwise a line
# must open with the claim ("// Generated by ...", "# This file was auto-generated ...",
# "_comment": "Generated by ...") and the header must also say "do not edit": prose that says
# another file "is generated by" something, or a value "generated from" its input, is no header.
LOUD = re.compile(r"^[^\w\n\"']*(?:[\"'][\w$-]+[\"']\s*:\s*[\"'])?(?:GENERATED (?:by|from)\b|@generated\b)", re.M)
SAYS_GENERATED = re.compile(
    r"^[^\w\n]*(?:[\w$-]+\"\s*:\s*\")?(?:this file (?:is|was|has been) (?:automatically )?)?"
    r"(?:auto-?generated|(?:code )?(?:generated|built) (?:by|from|with))\b",
    re.I | re.M)
DO_NOT_EDIT = re.compile(r"\bdo not edit\b", re.I)


@lru_cache(maxsize=None)
def glob_regex(pattern: str) -> re.Pattern[str]:
    """`**/` spans any directories (or none), `**` anything, `*` and `?` stay within one directory."""
    out, i = [], 0
    while i < len(pattern):
        if pattern.startswith("**/", i):
            out.append(r"(?:.*/)?")
            i += 3
        elif pattern.startswith("**", i):
            out.append(r".*")
            i += 2
        elif pattern[i] == "*":
            out.append(r"[^/]*")
            i += 1
        elif pattern[i] == "?":
            out.append(r"[^/]")
            i += 1
        else:
            out.append(re.escape(pattern[i]))
            i += 1
    return re.compile("".join(out) + r"\Z")


def matches(path: str, patterns: Iterable[str]) -> bool:
    return any(glob_regex(pattern).match(path) for pattern in patterns)


@dataclass
class Generator:
    id: str
    generator: str
    outputs: list[str]
    inputs: list[str]
    status: str

    def owns(self, path: str) -> bool:
        return matches(path, self.outputs)


@dataclass
class Rules:
    generators: list[Generator]
    conventions: list[str]
    committed: list[dict]
    baseline: set[str]
    # (output patterns, input regex) pairs from generated_outputs.py: committed exports.
    exports: list[tuple[tuple[str, ...], str]] = field(default_factory=list)

    def generator_of(self, path: str) -> Generator | None:
        return next((g for g in self.generators if g.owns(path)), None)

    def is_export(self, path: str) -> bool:
        return any(fnmatch.fnmatchcase(path, p) for patterns, _ in self.exports for p in patterns)

    def committed_by_design(self, path: str) -> bool:
        return any(matches(path, entry.get("paths", ())) for entry in self.committed)

    def covered(self, path: str) -> bool:
        """Owned by a generator whose outputs are still committed (pending cutover)."""
        found = self.generator_of(path)
        return (found is not None and found.status == "committed") or self.is_export(path)


def parse_rules(manifest_text: str, baseline_text: str, exports) -> Rules:
    data = json.loads(manifest_text)
    generators = []
    for entry in data.get("generators", ()):
        status = entry.get("status")
        if status not in ("committed", "build"):
            raise ValueError(f"{MANIFEST}: {entry.get('id')}: status must be committed or build, not {status!r}")
        generators.append(Generator(
            id=entry["id"], generator=entry["generator"], outputs=list(entry["outputs"]),
            inputs=list(entry.get("inputs", ())), status=status))
    ids = [g.id for g in generators]
    if len(ids) != len(set(ids)):
        raise ValueError(f"{MANIFEST}: duplicate generator ids")
    baseline = {line.strip() for line in baseline_text.splitlines() if line.strip() and not line.startswith("#")}
    return Rules(generators, list(data.get("conventions", ())), list(data.get("committed", ())), baseline,
                 list(exports))


def load_exports(source: str | None, settings_exports: str | None = None):
    """generated_outputs.OUTPUTS (from its source text) as (patterns, input regex) pairs; none without it.

    The module is run from a temporary directory, not the checkout, so every file it reads beside
    itself has to be written there too, at the same revision as the source: generated_outputs.py
    reads settings-exports.txt, the one list of the settings exports (#23915)."""
    if source is None:
        return []
    with tempfile.TemporaryDirectory() as tmp:
        module_path = Path(tmp) / "generated_outputs_for_guard.py"
        module_path.write_text(source, encoding="utf-8")
        if settings_exports is not None:
            (Path(tmp) / "settings-exports.txt").write_text(settings_exports, encoding="utf-8")
        spec = importlib.util.spec_from_file_location("generated_outputs_for_guard", module_path)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
    return [(tuple(patterns), inputs) for patterns, inputs, _ in module.OUTPUTS]


def git(repo: Path, *args: str, check: bool = True) -> str:
    result = subprocess.run(["git", "-C", str(repo), *args], capture_output=True, text=True, check=False)
    if check and result.returncode != 0:
        raise RuntimeError(f"git {' '.join(args)}: {result.stderr.strip()}")
    return result.stdout


def show(repo: Path, rev: str, path: str) -> str | None:
    result = subprocess.run(["git", "-C", str(repo), "show", f"{rev}:{path}"], capture_output=True, text=True,
                            check=False)
    return result.stdout if result.returncode == 0 else None


def rules_at(repo: Path, rev: str, exports=None) -> Rules | None:
    """The rules at `rev`, with that revision's own generated_outputs.py exports unless given."""
    manifest = show(repo, rev, MANIFEST)
    if manifest is None:
        return None
    if exports is None:
        exports = load_exports(show(repo, rev, OUTPUTS), show(repo, rev, SETTINGS_EXPORTS))
    return parse_rules(manifest, show(repo, rev, BASELINE) or "", exports)


def generated_header(head: bytes) -> bool:
    if b"\0" in head:
        return False
    lines = head.decode("utf-8", "replace").splitlines()[:HEADER_LINES]
    text = "\n".join(line[:HEADER_LINE_CHARS] for line in lines)
    return bool(LOUD.search(text) or (SAYS_GENERATED.search(text) and DO_NOT_EDIT.search(text)))


def read_head(repo: Path, path: str) -> bytes:
    full = repo / path
    if full.is_symlink() or not full.is_file():
        return b""
    try:
        with open(full, "rb") as handle:
            return handle.read(HEADER_BYTES)
    except OSError:
        return b""


def why_generated(rules: Rules, repo: Path, path: str) -> str | None:
    """Why `path` (in the working tree) is a generated file, or None."""
    if rules.committed_by_design(path):
        return None
    found = rules.generator_of(path)
    if found is not None:
        return f"{found.generator} writes it ({MANIFEST}: {found.id}, status {found.status})"
    if rules.is_export(path):
        return "the base autofix regenerates it (scripts/cmux-next/generated_outputs.py)"
    if matches(path, rules.conventions):
        return f"its name marks it generated ({MANIFEST} conventions)"
    if generated_header(read_head(repo, path)):
        return "its header says it is generated"
    return None


def tracked_files(repo: Path) -> list[str]:
    """Tracked regular files and symlinks at the working tree (no submodules)."""
    out = git(repo, "ls-files", "-s", "-z")
    paths = []
    for record in out.split("\0"):
        if not record:
            continue
        meta, path = record.split("\t", 1)
        if not meta.startswith("160000"):
            paths.append(path)
    return paths


def uncovered_generated(rules: Rules, repo: Path) -> list[str]:
    return sorted(p for p in tracked_files(repo) if not rules.covered(p) and why_generated(rules, repo, p))


def changes(repo: Path, base: str, head: str) -> list[tuple[str, str]]:
    out = git(repo, "diff", "--no-renames", "--name-status", "-z", base, head)
    fields = [f for f in out.split("\0") if f]
    return [(fields[i][0], fields[i + 1]) for i in range(0, len(fields), 2)]


def rule_changes(base: Rules, head: Rules, base_tracked: set[str]) -> list[str]:
    errors = []
    before = {g.id: g for g in base.generators}
    for g in head.generators:
        if g.status != "committed":
            continue
        old = before.get(g.id)
        if old is None or old.status != "committed":
            errors.append(
                f"{MANIFEST}: {g.id} is \"committed\" but the base has it "
                f"{'as ' + repr(old.status) if old else 'not at all'}. A generator's outputs may move out of git, "
                "never into it: generate them at build time (gitignore them) and give it status \"build\".")
            continue
        wider = [p for p in g.outputs if p not in old.outputs]
        if wider:
            errors.append(f"{MANIFEST}: {g.id} widens its committed outputs with {', '.join(wider)}. "
                          "A committed generator's outputs may only narrow.")
    old_exports = {p for patterns, _ in base.exports for p in patterns}
    for pattern in sorted({p for patterns, _ in head.exports for p in patterns} - old_exports):
        errors.append(f"{OUTPUTS}: {pattern} is a new committed export. Exports are committed generated "
                      "files; a new output belongs at build time (gitignored), not in the base autofix's list.")
    known = {json.dumps(e, sort_keys=True) for e in base.committed}
    for entry in head.committed:
        if json.dumps(entry, sort_keys=True) in known:
            continue
        if not re.match(r"https://", str(entry.get("ruling", ""))):
            errors.append(f"{MANIFEST}: the committed-by-design entry {entry.get('paths')} is new and has no "
                          "\"ruling\" link (the issue or comment that decided these files belong in git).")
    for path in sorted(head.baseline - base.baseline):
        if path not in base_tracked:
            errors.append(f"{BASELINE}: {path} is new to the baseline but the base does not track it. "
                          "The baseline only lists generated files git already had; it may only shrink.")
    return errors


def hand_edits(rules: Rules, changed: list[tuple[str, str]]) -> list[str]:
    paths = [path for _, path in changed]
    errors = []
    for status, path in changed:
        if status != "M":
            continue
        found = rules.generator_of(path)
        if found is None or not found.inputs or rules.is_export(path):
            continue
        sources = [found.generator, *found.inputs]
        if any(matches(other, sources) and not found.owns(other) for other in paths):
            continue
        errors.append(
            f"{path}: written by {found.generator}, but this pull request changes none of its inputs "
            f"({', '.join(sources)}). Edit the inputs and rerun the generator, or drop the change "
            f"(git checkout origin/feat-cmux-next -- {path}).")
    return errors


def check(repo: Path, base_rev: str, head_rev: str, exports=None) -> tuple[list[str], list[str]]:
    base = rules_at(repo, base_rev, exports)
    if base is None:
        return [], [f"The base has no {MANIFEST} yet; nothing to check."]
    head = rules_at(repo, head_rev, exports)
    if head is None:
        return [f"{MANIFEST} is deleted. It is the list of generators this guard reads; keep it."], []
    changed = changes(repo, base_rev, head_rev)
    errors: list[str] = []
    reported: set[str] = set()
    for status, path in changed:
        if status != "A" or base.covered(path):
            continue
        # The base's rules decide, and an output the change itself declares (say a new "build"
        # generator's) is generated too unless the head covers it (rule_changes judges that cover).
        why = why_generated(base, repo, path) or (None if head.covered(path) else why_generated(head, repo, path))
        if why:
            reported.add(path)
            errors.append(
                f"{path}: a new committed generated file ({why}). Generated files are build output: "
                "gitignore it and generate it where it is used (the build, the test preload, the install "
                "hook), the way the web bundles and the page strings are (ce0b9e76, #21946).")
    base_tracked = set(git(repo, "ls-tree", "-r", "--name-only", "-z", base_rev).split("\0")) - {""}
    errors += rule_changes(base, head, base_tracked)
    errors += hand_edits(base, changed)
    missing = [p for p in uncovered_generated(head, repo) if p not in head.baseline]
    # A file reported above is not reported twice. The rest are this change's when it touched the file
    # or uncovered one the base covered (a dropped baseline line, a narrowed generator); otherwise the
    # base tracks it uncovered already, which is the base's red and only a note here.
    touched = {path for _, path in changed}
    notes = []
    for path in missing:
        if path in reported:
            continue
        message = (f"{path}: tracked and generated ({why_generated(head, repo, path)}), but neither a "
                   f"committed generator in {MANIFEST} nor {BASELINE} lists it.")
        if path in touched or path in base.baseline or base.covered(path):
            errors.append(message)
        else:
            notes.append(f"{message} The base has it uncovered too (the base's red, not this change's).")
    tracked_now = set(tracked_files(repo))
    stale = sorted(p for p in head.baseline if p not in tracked_now)
    if stale:
        notes.append(f"{BASELINE} lists {len(stale)} file(s) git no longer tracks; drop them: {', '.join(stale[:20])}")
    return errors, notes


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = parser.add_subparsers(dest="command", required=True)
    run = sub.add_parser("check")
    run.add_argument("--repo", type=Path, default=Path("."))
    run.add_argument("--base", required=True)
    run.add_argument("--head", required=True)
    sub.add_parser("baseline").add_argument("--repo", type=Path, default=Path("."))
    args = parser.parse_args(argv)
    repo = args.repo.resolve()
    if args.command == "baseline":
        manifest = (repo / MANIFEST).read_text(encoding="utf-8")
        outputs = repo / OUTPUTS
        listed = repo / SETTINGS_EXPORTS
        exports = load_exports(outputs.read_text(encoding="utf-8") if outputs.is_file() else None,
                               listed.read_text(encoding="utf-8") if listed.is_file() else None)
        rules = parse_rules(manifest, "", exports)
        print("# Generated files git still tracks that no \"committed\" generator in generated-files.json covers.")
        print("# Shrink only: a cutover removes lines; nothing adds one (generated_files_guard.py).")
        for path in uncovered_generated(rules, repo):
            print(path)
        return 0
    errors, notes = check(repo, args.base, args.head)
    for note in notes:
        print(f"note: {note}")
    for error in errors:
        print(f"error: {error}")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
